//! Per-packet fixtures encoded by the real Artemis classes
//! (`tests/golden/packets/<group>/<Struct>[~case]@<s|c>-<version>.bin`,
//! generated by `scripts/packet-fixtures.sh`). Each must decode to the named
//! struct at that version and direction, and re-encode identically.

use std::path::{Path, PathBuf};

use saranga_core_protocol::{Context, Direction, Packet, read_frame};

fn fixtures() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/packets");
    let mut out = Vec::new();
    for group in std::fs::read_dir(root).unwrap().flatten() {
        for f in std::fs::read_dir(group.path()).unwrap().flatten() {
            if f.path().extension().is_some_and(|e| e == "bin") {
                out.push(f.path());
            }
        }
    }
    out.sort();
    out
}

/// Parses `<Struct>[~case]@<s|c>-<version>`.
fn parse_name(path: &Path) -> (String, Context) {
    let stem = path.file_stem().unwrap().to_str().unwrap();
    let (name, ctx) = stem.split_once('@').expect("name@dir-version");
    let name = name.split('~').next().unwrap().to_string();
    let (dir, version) = ctx.split_once('-').expect("dir-version");
    let direction = match dir {
        "s" => Direction::ToServer,
        "c" => Direction::ToClient,
        _ => panic!("{stem}: bad direction {dir}"),
    };
    (name, Context::new(direction, version.parse().unwrap()))
}

#[test]
fn packet_fixtures_roundtrip() {
    let files = fixtures();
    assert!(!files.is_empty(), "no packet fixtures found");
    let mut failures = Vec::new();
    for path in &files {
        let file = path.file_name().unwrap().to_string_lossy().into_owned();
        let (name, ctx) = parse_name(path);
        let bytes = std::fs::read(path).unwrap();
        let result = (|| {
            let (frame, used) = read_frame(&bytes)?.ok_or("truncated frame")?;
            if used != bytes.len() {
                return Err(format!("{} bytes after frame", bytes.len() - used).into());
            }
            let packet = Packet::decode(&frame, &ctx)?;
            if packet.name() != name {
                return Err(format!("decoded as {}", packet.name()).into());
            }
            if packet.encode_frame(frame.channel_id, &ctx) != bytes {
                return Err(format!("re-encode differs: {packet:?}").into());
            }
            Ok::<_, Box<dyn std::error::Error>>(())
        })();
        if let Err(e) = result {
            failures.push(format!("{file}: {e}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} fixtures failed:\n{}",
        failures.len(),
        files.len(),
        failures.join("\n")
    );
}
